//////////////////////////////////////////////////////
// Unendlicher Raum mit Quader-Tiling via Raymarching
//
// - Einfache Wiederholung (Tile) entlang XZ-Ebene
// - Kein Boden, sodass wir ins Unendliche schauen
// - Kamera fliegt mit iTime nach vorn
//
// Von ChatGPT
//////////////////////////////////////////////////////

// --------------------------------------------------
// 1) Hilfsfunktionen
// --------------------------------------------------

// Pseudozufall aus 3D => 1D (optional, wenn du Variation pro Tile willst)
float hash13(vec3 p) {
    p = fract(p * 0.3183099 + 0.1);
    p *= 17.0;
    return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
}

// Signierte Distanz zu einer Box (SDF).
// boxSize ist die halbe Ausdehnung (x, y, z).
float boxSDF(vec3 p, vec3 boxSize) {
    vec3 d = abs(p) - boxSize;
    return length(max(d, 0.0)) + min(max(d.x, max(d.y, d.z)), 0.0);
}

// Minimale Distanz (Union).
float opUnion(float d1, float d2) {
    return min(d1, d2);
}

// --------------------------------------------------
// 2) Szenen-Funktion: unendlich viele Quader
// --------------------------------------------------
//
// Wir wiederholen die Position p in einem Tile-Raster.
// Das heißt: p.xz = fract() => wir holen p in einen "Zellenraum".
//
// - Jedes Tile enthält eine Quader-SDF in der Mitte.
// - Optional könnte man pro Tile random Höhe oder Variation einbauen.
float mapScene(vec3 p)
{
    // A) Unendlich viele Wiederholungen in XZ:
    //
    //    Wir transformieren p.xz in den "lokalen" Tile-Bereich
    //    von -1..1, bei einer Tile-Größe von 2.0 in X und Z.
    //    So hat jedes Tile 2 Einheiten Breite und Tiefe.
    //
    //    (Alternativ: tileSize=4 => -2..2, etc.)
    //    Hier wählen wir 2.0 als Tile Size.
    float tileSize = 2.0;
    vec2 tile = floor(p.xz / tileSize);  
    vec2 localXZ = mod(p.xz, tileSize) - 0.5 * tileSize; 
    // => jetzt liegen localXZ in [-1..1].

    // B) Ein Box-SDF in diesem Tile, z.B. Box mit Ausdehnung 0.4 in XZ und 1.0 in Y.
    //    Die Y-Position bestimmen wir einfach aus p.y (kein Repeat in Y).
    //    => So schwebt alles in einem unendlichen Raum.
    vec3 localP = vec3(localXZ.x, p.y, localXZ.y);

    float distBox = boxSDF(localP, vec3(0.4, 1.0, 0.4));

    // => Zusätzlich kannst du Variation reinbringen, indem du den Hash-Wert
    //    pro Tile nimmst und z.B. die Höhe veränderst.
    //    Hier auskommentiert für maximale Einfachheit:
    /*
    float h = 1.0 + 2.0 * hash13(vec3(tile, 0.0));
    float distBox = boxSDF(vec3(localXZ.x, p.y, localXZ.y) - vec3(0.0, h*0.5-1.0, 0.0), 
                           vec3(0.4, h*0.5, 0.4));
    */

    // C) Keine anderen Objekte => Distance = distBox
    return distBox;
}

// --------------------------------------------------
// 3) Normalenberechnung (Gradient)
// --------------------------------------------------
vec3 calcNormal(vec3 p)
{
    const float eps = 0.001;
    vec2 e = vec2(eps, 0.0);
    float d  = mapScene(p);
    float dx = mapScene(p + vec3(e.x, e.y, e.y)) - d;
    float dy = mapScene(p + vec3(e.y, e.x, e.y)) - d;
    float dz = mapScene(p + vec3(e.y, e.y, e.x)) - d;
    return normalize(vec3(dx, dy, dz));
}

// --------------------------------------------------
// 4) Raymarch
// --------------------------------------------------
float rayMarch(vec3 ro, vec3 rd, out vec3 hitPos, out vec3 hitNormal)
{
    const int   MAX_STEPS = 80;
    const float HIT_EPS   = 0.002;
    const float MAX_DIST  = 100.0;

    float t = 0.0;
    for(int i = 0; i < MAX_STEPS; i++)
    {
        vec3 pos = ro + rd * t;
        float distToScene = mapScene(pos);
        if(distToScene < HIT_EPS) {
            // Treffer
            hitPos = pos;
            hitNormal = calcNormal(pos);
            return t;
        }
        t += distToScene * 0.8;
        if(t > MAX_DIST) break;
    }
    return -1.0; // kein Treffer
}

// --------------------------------------------------
// 5) Beleuchtung
// --------------------------------------------------
vec3 lighting(vec3 p, vec3 n, vec3 rd)
{
    // Licht von schräg oben
    vec3 lightDir = normalize(vec3(0.5, 1.0, 0.3));

    // Ambient
    vec3 colAmbient = vec3(0.25, 0.3, 0.35);

    // Diffuse
    float diff = max(dot(n, lightDir), 0.0);
    vec3 colDiffuse = vec3(0.9, 0.8, 0.7) * diff;

    // Specular
    vec3 r = reflect(-lightDir, n);
    float spec = pow(max(dot(r, -rd), 0.0), 16.0);
    vec3 colSpec = vec3(1.0) * spec * 0.4;

    return colAmbient + colDiffuse + colSpec;
}

// --------------------------------------------------
// 6) Nebel (optional)
// --------------------------------------------------
vec3 applyFog(vec3 rgb, float dist, float fogDensity)
{
    vec3 fogColor = vec3(0.7, 0.8, 1.0);
    float fogFactor = 1.0 - exp(-dist * fogDensity);
    return mix(rgb, fogColor, fogFactor);
}

// --------------------------------------------------
// 7) mainImage
// --------------------------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    //------------------------------------------
    // A) Normierte Koordinaten
    //------------------------------------------
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    //------------------------------------------
    // B) Kamera-Setup
    //------------------------------------------
    // ro: Kamera-Position
    // => Wir fliegen nach vorn in +Z-Richtung
    float speed = 2.0;
    vec3 ro = vec3(0.0, 0.0, iTime * speed);

    // Wir schauen nach vorne in Z-Richtung
    // => forward
    vec3 forward = normalize(vec3(0.0, 0.0, 1.0));

    // "Rechts" und "Oben"
    vec3 right = normalize(cross(forward, vec3(0.0, 1.0, 0.0)));
    vec3 up    = cross(right, forward);

    // Ray-Direction
    vec3 rd = normalize(uv.x * right + uv.y * up + forward);

    //------------------------------------------
    // C) Raymarch
    //------------------------------------------
    vec3 hitPos, hitNormal;
    float t = rayMarch(ro, rd, hitPos, hitNormal);

    // Hintergrundfarbe
    vec3 col = vec3(0.02, 0.02, 0.04); // Dunkler Weltraum

    if(t > 0.0)
    {
        // Treffer => Beleuchtung
        vec3 shade = lighting(hitPos, hitNormal, rd);

        // Materialfarbe (leichter Metallton)
        vec3 matCol = vec3(0.6, 0.6, 0.65);

        col = matCol * shade;
    }

    //------------------------------------------
    // D) Nebel (optional)
    //------------------------------------------
    float distVal = (t > 0.0) ? t : 50.0;
    col = applyFog(col, distVal, 0.03);

    fragColor = vec4(col, 1.0);
}
